+      .quiz-card {
+        padding: 24px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="quiz-card">
+    <h1>Computer Languages Quiz</h1>
+    <p class="intro">Select all answers that apply for each question, then submit to see your score.</p>
+
+    <form id="quiz-form">
+      <div class="form-field">
+        <div class="question-title" id="question-1-title">1. Which of these are programming languages?</div>
+        <p class="help-text" id="question-1-help">Pick every option that is used to write software, not just to style or structure web pages.</p>
+        <div class="choices" role="group" aria-labelledby="question-1-title" aria-describedby="question-1-help">
+          <label class="choice"><input type="checkbox" name="q1" value="Python">Python</label>
+          <label class="choice"><input type="checkbox" name="q1" value="HTML">HTML</label>
+          <label class="choice"><input type="checkbox" name="q1" value="Java">Java</label>
+          <label class="choice"><input type="checkbox" name="q1" value="CSS">CSS</label>
+        </div>
+      </div>
+
+      <div class="form-field">
+        <div class="question-title" id="question-2-title">2. Which languages are commonly used for web development?</div>
+        <div class="choices" role="group" aria-labelledby="question-2-title">
+          <label class="choice"><input type="checkbox" name="q2" value="JavaScript">JavaScript</label>
+          <label class="choice"><input type="checkbox" name="q2" value="Ruby">Ruby</label>
+          <label class="choice"><input type="checkbox" name="q2" value="C">C</label>
+          <label class="choice"><input type="checkbox" name="q2" value="TypeScript">TypeScript</label>
+        </div>
+      </div>
+
+      <div class="form-field">
+        <div class="question-title" id="question-3-title">3. Which of these languages are strongly associated with systems programming?</div>
+        <div class="choices" role="group" aria-labelledby="question-3-title">
+          <label class="choice"><input type="checkbox" name="q3" value="Rust">Rust</label>
+          <label class="choice"><input type="checkbox" name="q3" value="Go">Go</label>
+          <label class="choice"><input type="checkbox" name="q3" value="C++">C++</label>
+          <label class="choice"><input type="checkbox" name="q3" value="SQL">SQL</label>
+        </div>
+      </div>
+
+      <button type="submit">Submit Quiz</button>
+      <p id="results" aria-live="polite"></p>
+    </form>
+  </main>
+
+  <script>
+    const answerKey = {
+      q1: ["Python", "Java"],
+      q2: ["JavaScript", "Ruby", "TypeScript"],
+      q3: ["Rust", "Go", "C++"]
+    };
+
+    const quizForm = document.getElementById("quiz-form");
+    const results = document.getElementById("results");
+
+    function getSelectedValues(questionName) {
+      return Array.from(document.querySelectorAll(`input[name="${questionName}"]:checked`))
+        .map((input) => input.value)
+        .sort();
+    }
+
+    function matchesAnswer(questionName) {
+      const selected = getSelectedValues(questionName);
+      const correct = [...answerKey[questionName]].sort();
+
+      return selected.length === correct.length && selected.every((value, index) => value === correct[index]);
+    }
+
+    quizForm.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const totalQuestions = Object.keys(answerKey).length;
+      const score = Object.keys(answerKey).filter(matchesAnswer).length;
+
+      results.textContent = `You scored ${score} out of ${totalQuestions}.`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
